local RopeMaker = {}
local PRODUCTS = {
    iron_rope = { name = "Železna vrv", ironCost = 1, woodCost = 2, leatherCost = 3, time = 5, cost = 145, prestige = 3, happiness = 2, description = "Železna vrv za sidra in gradnjo." },
    bronze_rope = { name = "Bronasta vrv", bronzeCost = 1, ironCost = 1, woodCost = 2, leatherCost = 3, time = 7, cost = 350, prestige = 5, happiness = 3, description = "Bronasta vrv za trdovratne uporabe." },
    silver_rope = { name = "Srebrna vrv", silverCost = 1, bronzeCost = 1, ironCost = 1, woodCost = 2, leatherCost = 3, time = 11, cost = 850, prestige = 10, happiness = 4, description = "Srebrna vrv za plemiške ladje." },
    gilded_rope = { name = "Pozlačena vrv", goldCost = 1, silverCost = 1, bronzeCost = 1, woodCost = 2, leatherCost = 3, time = 15, cost = 1820, prestige = 19, happiness = 5, description = "Pozlačena vrv za dvorne prireditve." },
    jewel_set_rope = { name = "Draguljasta vrv", goldCost = 2, silverCost = 1, jewelCost = 1, bronzeCost = 1, woodCost = 2, leatherCost = 3, time = 19, cost = 3950, prestige = 35, happiness = 7, description = "Draguljasta vrv za kraljeve slovesnosti." },
    royal_sovereign_rope = { name = "Kraljevski suverena vrv", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 3, leatherCost = 4, time = 26, cost = 8500, prestige = 67, happiness = 13, description = "Suverena vrv z biseri za krono." },
}
local BUILDINGS = {
    rope_workshop = { name = "Vrvarna delavnica", cost = { gold = 305, wood = 185, stone = 125, iron = 6 }, upkeep = 5, qualityBonus = 5 },
    rope_house = { name = "Vrvarna hiša", cost = { gold = 1135, wood = 365, stone = 260, silver = 6, iron = 6 }, upkeep = 24, qualityBonus = 18 },
    master_rope_atelier = { name = "Mojstrski vrvarski atelje", cost = { gold = 2880, wood = 425, stone = 500, silver = 33, gold = 6 }, upkeep = 68, qualityBonus = 30 },
    sovereign_rope_palace = { name = "Suverena vrvarna palača", cost = { gold = 12480, wood = 660, stone = 805, gold = 80, jewel = 18 }, upkeep = 246, qualityBonus = 55, prestigeBonus = 50 },
}
RopeMaker.ironStock = 10; RopeMaker.bronzeStock = 8; RopeMaker.woodStock = 16; RopeMaker.leatherStock = 14; RopeMaker.silverStock = 8; RopeMaker.goldStock = 6; RopeMaker.jewelStock = 4; RopeMaker.pearlStock = 4
RopeMaker.productStock = {}; RopeMaker.buildings = {}; RopeMaker.maker = nil; RopeMaker.activeMaking = {}; RopeMaker.totalProducts = 0; RopeMaker.dayTimer = 0
function RopeMaker.init() RopeMaker.ironStock=10; RopeMaker.bronzeStock=8; RopeMaker.woodStock=16; RopeMaker.leatherStock=14; RopeMaker.silverStock=8; RopeMaker.goldStock=6; RopeMaker.jewelStock=4; RopeMaker.pearlStock=4; RopeMaker.productStock={}; RopeMaker.buildings={}; RopeMaker.maker=nil; RopeMaker.activeMaking={}; RopeMaker.totalProducts=0; RopeMaker.dayTimer=0; print("[RopeMaker] Royal Rope Maker System initialized (6 products, 4 buildings)") end
function RopeMaker.hireMaker(n,s) s=s or math.random(55,90); local c=570+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; RopeMaker.maker={name=n or ("Vrvar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Vrvar najet: %s (spretnost: %d)",RopeMaker.maker.name,s),"success") end; return true end
function RopeMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function RopeMaker.build(id) local ok,e=RopeMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(RopeMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function RopeMaker.getQualityBonus() local b=0; for _,bd in ipairs(RopeMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function RopeMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and RopeMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and RopeMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and RopeMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and RopeMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and RopeMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and RopeMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and RopeMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and RopeMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #RopeMaker.buildings==0 then return false,"Potrebna vrvarna delavnica" end; if not RopeMaker.maker then return false,"Potreben vrvar" end; return true end
function RopeMaker.make(pt,qty) qty=qty or 1; local ok,e=RopeMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then RopeMaker.ironStock=RopeMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then RopeMaker.bronzeStock=RopeMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then RopeMaker.woodStock=RopeMaker.woodStock-d.woodCost*qty end; if d.leatherCost then RopeMaker.leatherStock=RopeMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then RopeMaker.silverStock=RopeMaker.silverStock-d.silverCost*qty end; if d.goldCost then RopeMaker.goldStock=RopeMaker.goldStock-d.goldCost*qty end; if d.jewelCost then RopeMaker.jewelStock=RopeMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then RopeMaker.pearlStock=RopeMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if RopeMaker.maker then t=math.max(1,t-math.floor(RopeMaker.maker.skill/13)) end; table.insert(RopeMaker.activeMaking,{id="rope_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function RopeMaker.completeMaking(m) local q=1.0+(RopeMaker.getQualityBonus()/100); if RopeMaker.maker then q=q+(RopeMaker.maker.skill/140) end; q=math.min(2.5,q); RopeMaker.productStock[m.productType]=(RopeMaker.productStock[m.productType] or 0)+m.quantity; RopeMaker.totalProducts=RopeMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if RopeMaker.maker then RopeMaker.maker.itemsMade=RopeMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then RopeMaker.maker.skill=math.min(100,RopeMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Vrv izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"rope.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function RopeMaker.update(dt) if not _G.state then return end; RopeMaker.dayTimer=RopeMaker.dayTimer+dt; if RopeMaker.dayTimer>=30 then RopeMaker.dayTimer=0; for i=#RopeMaker.activeMaking,1,-1 do local m=RopeMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then RopeMaker.completeMaking(m); table.remove(RopeMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(RopeMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if RopeMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function RopeMaker.getStats() return {ironStock=RopeMaker.ironStock,bronzeStock=RopeMaker.bronzeStock,woodStock=RopeMaker.woodStock,leatherStock=RopeMaker.leatherStock,silverStock=RopeMaker.silverStock,goldStock=RopeMaker.goldStock,jewelStock=RopeMaker.jewelStock,pearlStock=RopeMaker.pearlStock,productStock=RopeMaker.productStock,numBuildings=#RopeMaker.buildings,hasMaker=RopeMaker.maker~=nil,makerName=RopeMaker.maker and RopeMaker.maker.name or "—",makerSkill=RopeMaker.maker and RopeMaker.maker.skill or 0,activeMaking=#RopeMaker.activeMaking,totalProducts=RopeMaker.totalProducts} end
return RopeMaker
